"""M5: additive catalog, reference ranges, service links and versioned results."""
TABLES = ('lab_tests','lab_reference_ranges','lab_service_tests','lab_reports','lab_results')
# Framework only: no clinical reference values. Units must be reviewed locally.
FRAMEWORK = {
 'hematology': [('WBC','Bạch cầu','G/L'),('NEU%','Tỷ lệ bạch cầu trung tính','%'),('LYM%','Tỷ lệ lympho','%'),('MON%','Tỷ lệ mono','%'),('EOS%','Tỷ lệ ái toan','%'),('BAS%','Tỷ lệ ái kiềm','%'),('NEU#','Bạch cầu trung tính','G/L'),('LYM#','Lympho','G/L'),('MON#','Mono','G/L'),('EOS#','Ái toan','G/L'),('BAS#','Ái kiềm','G/L'),('RBC','Hồng cầu','T/L'),('HGB','Hemoglobin','g/L'),('HCT','Hematocrit','%'),('MCV','Thể tích trung bình hồng cầu','fL'),('MCH','Lượng hemoglobin trung bình hồng cầu','pg'),('MCHC','Nồng độ hemoglobin trung bình hồng cầu','g/L'),('RDW-CV','Độ phân bố hồng cầu','%'),('PLT','Tiểu cầu','G/L'),('MPV','Thể tích trung bình tiểu cầu','fL'),('PDW','Độ phân bố tiểu cầu','%'),('PCT','Thể tích khối tiểu cầu','%')],
 'biochemistry': [('GLU','Glucose','mmol/L'),('URE','Urê','mmol/L'),('CRE','Creatinin','µmol/L'),('UA','Acid uric','µmol/L'),('AST','AST','U/L'),('ALT','ALT','U/L'),('GGT','GGT','U/L'),('CHOL','Cholesterol toàn phần','mmol/L'),('TG','Triglycerid','mmol/L'),('HDL','HDL cholesterol','mmol/L'),('LDL','LDL cholesterol','mmol/L'),('BIL-T','Bilirubin toàn phần','µmol/L'),('BIL-D','Bilirubin trực tiếp','µmol/L'),('TP','Protein toàn phần','g/L'),('ALB','Albumin','g/L'),('NA','Natri','mmol/L'),('K','Kali','mmol/L'),('CL','Clorid','mmol/L')],
 'urine': [('GLU','Glucose','mmol/L'),('BIL','Bilirubin',''),('KET','Ceton','mmol/L'),('SG','Tỷ trọng',''),('BLO','Máu',''),('PH','pH',''),('PRO','Protein','g/L'),('URO','Urobilinogen','µmol/L'),('NIT','Nitrit',''),('LEU','Bạch cầu','')],
}


def migrate_m5(c, postgres=False):
    if c.execute('SELECT 1 FROM schema_migrations WHERE version=9').fetchone(): return
    identity='BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY' if postgres else 'INTEGER PRIMARY KEY AUTOINCREMENT'
    for sql in [
      f'''CREATE TABLE lab_tests(id {identity},code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,abbreviation TEXT NOT NULL,
        group_name TEXT NOT NULL CHECK(group_name IN ('hematology','biochemistry','urine','other')),
        result_type TEXT NOT NULL CHECK(result_type IN ('number','choice','text')),unit TEXT NOT NULL DEFAULT '',
        decimals INTEGER NOT NULL DEFAULT 2,print_order INTEGER NOT NULL DEFAULT 0,active INTEGER NOT NULL DEFAULT 1,choices TEXT NOT NULL DEFAULT '[]')''',
      f'''CREATE TABLE lab_reference_ranges(id {identity},test_id INTEGER NOT NULL REFERENCES lab_tests(id),
        sex TEXT NOT NULL,age_from INTEGER,age_to INTEGER,lower_value TEXT,upper_value TEXT,normal_value TEXT NOT NULL DEFAULT '')''',
      '''CREATE TABLE lab_service_tests(service_id INTEGER NOT NULL REFERENCES service_catalog(id),test_id INTEGER NOT NULL REFERENCES lab_tests(id),PRIMARY KEY(service_id,test_id))''',
      f'''CREATE TABLE lab_reports(id {identity},order_id INTEGER NOT NULL REFERENCES orders(id),
        status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','pending_review','approved')),version INTEGER NOT NULL DEFAULT 0,
        replaces_id INTEGER UNIQUE REFERENCES lab_reports(id),adjustment_reason TEXT NOT NULL DEFAULT '',
        sample_at TEXT,result_at TEXT,performed_by INTEGER REFERENCES users(id),approved_by INTEGER REFERENCES users(id),
        approved_at TEXT,comment TEXT NOT NULL DEFAULT '',snapshot TEXT,created_at TEXT NOT NULL)''',
      f'''CREATE TABLE lab_results(id {identity},report_id INTEGER NOT NULL REFERENCES lab_reports(id),test_id INTEGER NOT NULL REFERENCES lab_tests(id),
        definition TEXT NOT NULL,value TEXT NOT NULL DEFAULT '',note TEXT NOT NULL DEFAULT '',UNIQUE(report_id,test_id))''',
      'CREATE INDEX idx_m5_reports_order ON lab_reports(order_id,id)',
      'CREATE INDEX idx_m5_reports_queue ON lab_reports(status,id)',
      'CREATE INDEX idx_m5_reference ON lab_reference_ranges(test_id,sex)',
      'CREATE INDEX idx_m5_results_test ON lab_results(test_id,report_id)',
    ]: c.execute(sql)
    for group,items in FRAMEWORK.items():
        for position,(abbr,name,unit) in enumerate(items,1):
            c.execute('INSERT INTO lab_tests(code,name,abbreviation,group_name,result_type,unit,decimals,print_order) VALUES(?,?,?,?,?,?,?,?)',
                      (group.upper()+'-'+abbr,name,abbr,group,'text' if group=='urine' else 'number',unit,2,position))
    c.execute('INSERT INTO schema_migrations(version) VALUES(9)')
